class Solution {
    public int racecar(int target) {
        int[] dp = new int[target + 1];
        java.util.Arrays.fill(dp, Integer.MAX_VALUE);
        for (int t = 1; t <= target; t++) {
            int k = 0;
            while ((1 << k) - 1 < t) k++;
            int pos = (1 << k) - 1;
            if (pos == t) { dp[t] = k; continue; }
            dp[t] = k + 1 + dp[pos - t];
            for (int j = 0; j < k - 1; j++) {
                int pos2 = (1 << (k - 1)) - 1 - ((1 << j) - 1);
                dp[t] = Math.min(dp[t], (k - 1) + 1 + j + 1 + dp[t - pos2]);
            }
        }
        return dp[target];
    }
}

import java.util.*;

class Solution {
    public int racecar(int target) {
        Set<String> visited = new HashSet<>();
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{0, 1});
        visited.add("0,1");
        int steps = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                int[] cur = queue.poll();
                int pos = cur[0], speed = cur[1];
                if (pos == target) return steps;
                int newPos = pos + speed;
                int newSpeed = speed * 2;
                String key1 = newPos + "," + newSpeed;
                if (newPos > 0 && newPos < 2 * target && !visited.contains(key1)) {
                    visited.add(key1);
                    queue.offer(new int[]{newPos, newSpeed});
                }
                int revSpeed = speed > 0 ? -1 : 1;
                String key2 = pos + "," + revSpeed;
                if (!visited.contains(key2)) {
                    visited.add(key2);
                    queue.offer(new int[]{pos, revSpeed});
                }
            }
            steps++;
        }
        return -1;
    }
}

class Solution {
    private int[] memo;

    public int racecar(int target) {
        memo = new int[target + 1];
        return solve(target);
    }

    private int solve(int target) {
        if (memo[target] != 0) {
            return memo[target];
        }

        int forwardSteps = 32 - Integer.numberOfLeadingZeros(target);
        int fullDistance = (1 << forwardSteps) - 1;
        if (fullDistance == target) {
            memo[target] = forwardSteps;
            return forwardSteps;
        }

        int best = forwardSteps + 1 + solve(fullDistance - target);
        int beforeTargetSteps = forwardSteps - 1;
        int beforeTargetDistance = (1 << beforeTargetSteps) - 1;
        for (int reverseSteps = 0; reverseSteps < beforeTargetSteps; reverseSteps++) {
            int reverseDistance = (1 << reverseSteps) - 1;
            int remaining = target - (beforeTargetDistance - reverseDistance);
            best = Math.min(best, beforeTargetSteps + 1 + reverseSteps + 1 + solve(remaining));
        }

        memo[target] = best;
        return best;
    }
}

import java.util.*;

class Solution {
    public int racecar(int target) {
        int limit = target * 2 + 4;
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(state -> state[2]));
        Set<Long> settled = new HashSet<>();
        pq.offer(new int[]{0, 1, 0});

        while (!pq.isEmpty()) {
            int[] state = pq.poll();
            int position = state[0];
            int speed = state[1];
            int steps = state[2];
            long key = encode(position, speed, limit);
            if (!settled.add(key)) {
                continue;
            }
            if (position == target) {
                return steps;
            }

            int acceleratedPosition = position + speed;
            int acceleratedSpeed = speed * 2;
            if (acceleratedPosition > -limit && acceleratedPosition < limit) {
                pq.offer(new int[]{acceleratedPosition, acceleratedSpeed, steps + 1});
            }

            int reversedSpeed = speed > 0 ? -1 : 1;
            pq.offer(new int[]{position, reversedSpeed, steps + 1});
        }
        return -1;
    }

    private long encode(int position, int speed, int limit) {
        return (((long) position + limit) << 32) ^ (speed & 0xffffffffL);
    }
}

import java.util.*;

class Solution {
    public int racecar(int target) {
        int limit = target * 2 + 4;
        ArrayDeque<int[]> queue = new ArrayDeque<>();
        Set<Long> visited = new HashSet<>();
        queue.offer(new int[]{0, 1});
        visited.add(encode(0, 1, limit));
        int instructions = 0;

        while (!queue.isEmpty()) {
            for (int size = queue.size(); size > 0; size--) {
                int[] state = queue.poll();
                int position = state[0];
                int speed = state[1];
                if (position == target) {
                    return instructions;
                }

                int nextPosition = position + speed;
                int nextSpeed = speed * 2;
                if (nextPosition > -limit && nextPosition < limit) {
                    long acceleratedKey = encode(nextPosition, nextSpeed, limit);
                    if (visited.add(acceleratedKey)) {
                        queue.offer(new int[]{nextPosition, nextSpeed});
                    }
                }

                int reverseSpeed = speed > 0 ? -1 : 1;
                long reverseKey = encode(position, reverseSpeed, limit);
                if (visited.add(reverseKey)) {
                    queue.offer(new int[]{position, reverseSpeed});
                }
            }
            instructions++;
        }
        return -1;
    }

    private long encode(int position, int speed, int limit) {
        return (((long) position + limit) << 32) ^ (speed & 0xffffffffL);
    }
}
